            walls.append(('v', c, vals[0]))
    if not walls:
        return [row[:] for row in grid]
    # The long full-width/full-height separator is the movement boundary.
    axis, wall, _ = max(walls, key=lambda x: h*w)
    points = [(r,c) for r in range(h) for c in range(w) if grid[r][c] != bg and not (r == wall if axis == 'h' else c == wall)]
    if not points:
        return [row[:] for row in grid]
    out = [row[:] for row in grid]
    for r,c in points:
        out[r][c] = bg
    if axis == 'h':
        if max(r for r,c in points) < wall:
            dr = wall - 1 - max(r for r,c in points)
            stripe = min(r for r,c in points) + dr - 1
